package ir.masirbandegi.app;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Typeface;import android.graphics.Color;import android.view.*;import android.widget.*;import android.database.Cursor;
import java.time.*;import java.util.*;

public class MainActivity extends Activity {
  Store store; LinearLayout root,body,bar; String day; int bg=0xfff4f0e6, ink=0xff183d36, gold=0xffb68b45;
  @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(ink);getWindow().setNavigationBarColor(ink);store=new Store(this);day=Jalali.format(LocalDate.now());store.ensureDay(day);home();}
  TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.RIGHT);t.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));t.setPadding(8,8,8,8);return t;}
  LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
  void base(String title){root=column();root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);root.setBackgroundColor(bg);setContentView(root); TextView h=text("✦  مسیر بندگی",23,Color.WHITE);h.setTypeface(null,Typeface.BOLD);h.setBackgroundColor(ink);h.setPadding(18,22,18,22);root.addView(h); TextView sub=text(title,19,ink);sub.setTypeface(null,Typeface.BOLD);sub.setPadding(16,16,16,10);root.addView(sub);ScrollView sc=new ScrollView(this);body=column();body.setPadding(14,0,14,20);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));bar=new LinearLayout(this);bar.setBackgroundColor(ink);String[] names={"خانه","برنامه","محاسبه نفس","مهارت","گزارش","تنظیمات"};for(int i=0;i<names.length;i++){final int k=i;Button b=button(names[i]);b.setTextSize(10);b.setTextColor(Color.WHITE);b.setBackgroundColor(ink);bar.addView(b,new LinearLayout.LayoutParams(0,54,1));b.setOnClickListener(v->navigate(k));}root.addView(bar);}
  Button button(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(ink);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xffe6d9bf));return b;}
  void card(String s){TextView t=text(s,15,ink);t.setBackgroundColor(Color.WHITE);t.setPadding(16,14,16,14);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,5,0,5);body.addView(t,p);}
  void navigate(int k){switch(k){case 0:home();break;case 1:plan();break;case 2:reflection();break;case 3:skills();break;case 4:reports();break;default:settings();}}
  void home(){base("امروز · "+day+" · "+LocalDate.now().getDayOfWeek());int[] c=store.counts(day);int pct=c[0]==0?0:(c[1]*100/c[0]);card("السلام علیک یا صاحب‌الزمان (عج)\n\nپیشرفت امروز: "+pct+"٪\nانجام‌شده: "+c[1]+"  |  باقی‌مانده: "+(c[0]-c[1]));card("پیام امروز\nقدم‌های کوچک و پیوسته، از تصمیم‌های بزرگ و ناپایدار ارزشمندترند.");card("یادآوری\nهیچ کاری بدون تأیید شما انجام‌شده ثبت نمی‌شود.");Button p=button("مشاهده برنامه امروز");body.addView(p);p.setOnClickListener(v->plan());Button r=button("ثبت محاسبه نفس امشب");body.addView(r);r.setOnClickListener(v->reflection());}
  void plan(){base("برنامه امروز");int[] counts=store.counts(day);card("تاریخ شمسی: "+day+"     پیشرفت: "+(counts[0]==0?0:counts[1]*100/counts[0])+"٪");Cursor c=store.tasks(day);while(c.moveToNext()){long id=c.getLong(0);String title=c.getString(1),cat=c.getString(2);int st=c.getInt(3);String state=st==1?"✓ انجام شد":st==2?"◐ ناقص":"○ تعیین وضعیت";LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setBackgroundColor(Color.WHITE);row.setPadding(8,4,8,4);TextView label=text(title+"\n"+cat,14,ink);row.addView(label,new LinearLayout.LayoutParams(0,-2,1));Button b=button(state);row.addView(b);b.setOnClickListener(v->{String[] opts={"انجام شد","ناقص انجام شد","انجام نشد"};new AlertDialog.Builder(this).setTitle(title).setItems(opts,(d,w)->{store.status(id,w==0?1:w==1?2:0);plan();}).show();});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,3,0,3);body.addView(row,lp);}c.close();Button add=button("＋ افزودن فعالیت شخصی");body.addView(add);add.setOnClickListener(v->{EditText e=new EditText(this);e.setHint("عنوان فعالیت");new AlertDialog.Builder(this).setTitle("فعالیت جدید").setView(e).setPositiveButton("ذخیره",(d,w)->{if(e.getText().length()>0){store.addTask(day,e.getText().toString());plan();}}).setNegativeButton("انصراف",null).show();});}
  void reflection(){base("محاسبه نفس شبانه");String[] qs={"امروز چه کار خوبی انجام دادم؟","کجا کوتاهی کردم؟","آیا حق کسی را ضایع کردم؟","آیا به پدر و مادرم احترام گذاشتم؟","آیا از زمانم درست استفاده کردم؟","بابت چه چیزی شکرگزارم؟","فردا چه چیزی را اصلاح می‌کنم؟"};EditText[] es=new EditText[qs.length];LinearLayout form=column();String old=store.reflection(day);for(int i=0;i<qs.length;i++){TextView q=text(qs[i],15,ink);form.addView(q);es[i]=new EditText(this);es[i].setMinLines(1);es[i].setGravity(Gravity.RIGHT);es[i].setTextColor(ink);form.addView(es[i]);}if(!old.isEmpty()){String[] lines=old.split("\\n",-1);for(int i=0;i<Math.min(lines.length,es.length);i++)es[i].setText(lines[i]);}body.addView(form);Button save=button("ذخیره محاسبه نفس");body.addView(save);save.setOnClickListener(v->{StringBuilder s=new StringBuilder();for(int i=0;i<es.length;i++){if(i>0)s.append('\n');s.append(es[i].getText());}store.saveReflection(day,s.toString());new AlertDialog.Builder(this).setMessage("یادداشت امروز ذخیره شد.").setPositiveButton("باشه",null).show();});}
  void skills(){base("مهارت‌آموزی");card("اولویت‌ها: امنیت شبکه ۳ جلسه · زبان عبری ۲ جلسه · OSINT یک جلسه · هوش مصنوعی یک جلسه · عکاسی یک جلسه در هفته");EditText skill=new EditText(this);skill.setHint("مهارت (مثلاً امنیت شبکه)");body.addView(skill);EditText topic=new EditText(this);topic.setHint("موضوع جلسه");body.addView(topic);EditText mins=new EditText(this);mins.setHint("مدت مطالعه به دقیقه");mins.setInputType(2);body.addView(mins);EditText progress=new EditText(this);progress.setHint("پیشرفت ۰ تا ۱۰۰");progress.setInputType(2);body.addView(progress);EditText note=new EditText(this);note.setHint("یادداشت آموزشی");body.addView(note);Button save=button("ثبت جلسه یادگیری");body.addView(save);save.setOnClickListener(v->{try{store.addLearning(day,skill.getText().toString(),topic.getText().toString(),Integer.parseInt(mins.getText().toString()),Integer.parseInt(progress.getText().toString()),note.getText().toString());new AlertDialog.Builder(this).setMessage("جلسه ثبت شد.").setPositiveButton("باشه",null).show();}catch(Exception ex){new AlertDialog.Builder(this).setMessage("مدت و درصد پیشرفت را عددی وارد کنید.").setPositiveButton("باشه",null).show();}});}
  void reports(){base("گزارش امروز");int[] c=store.counts(day);card("تعداد فعالیت‌ها: "+c[0]+"\nانجام‌شده: "+c[1]+"\nناقص: "+c[2]+"\nانجام‌نشده یا تعیین‌نشده: "+(c[0]-c[1]-c[2])+"\nدرصد انجام کامل: "+(c[0]==0?0:c[1]*100/c[0])+"٪");card("این نسخه گزارش پایه روز جاری را محاسبه می‌کند. تحلیل روند هفتگی/ماهانه و نمودارهای تجمیعی هنوز پیاده‌سازی نشده‌اند.");}
  void settings(){base("تنظیمات و پشتیبان‌گیری");card("اطلاعات اصلی به‌صورت محلی در پایگاه داده SQLite گوشی ذخیره می‌شود.");String[] themes={"سبز حرم رضوی","طلایی کربلا","فیروزه‌ای نجف","آبی کاظمین","سبز سامرا","سفید مسجدالحرام","سبز مسجدالنبی"};Button theme=button("انتخاب حال‌وهوای رنگی");body.addView(theme);theme.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("تم برنامه").setItems(themes,(d,w)->{int[] colors={0xfff4f0e6,0xfff6eee2,0xffeaf4f1,0xffedf2f6,0xffeef3e9,0xfff7f4eb,0xffeaf2ef};bg=colors[w];home();}).show());Button backup=button("نمایش داده‌های پشتیبان JSON");body.addView(backup);backup.setOnClickListener(v->{int[] c=store.counts(day);String json="{\"date\":\""+day+"\",\"tasks_total\":"+c[0]+",\"done\":"+c[1]+",\"partial\":"+c[2]+",\"reflection\":\""+store.reflection(day).replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n")+"\"}";EditText e=new EditText(this);e.setText(json);e.setTextIsSelectable(true);new AlertDialog.Builder(this).setTitle("JSON پایه روز جاری").setView(e).setPositiveButton("بستن",null).show();});card("محدودیت نسخه فعلی: اعلان زمان‌بندی‌شده، بازیابی کامل JSON، خروجی PDF، قفل PIN/اثر انگشت، تصاویر آفلاین اماکن مقدس و دستیار هوش مصنوعی آنلاین هنوز اضافه نشده‌اند. هیچ درخواست آنلاین یا تحلیل ساختگی انجام نمی‌شود.");}
}
